67	func (s *APIV1Service) acquireImageProcessingSlot(ctx context.Context) (func(), error) {
68		if s.imageProcessingSemaphore == nil {
69			return func() {}, nil
70		}
71		if err := s.imageProcessingSemaphore.Acquire(ctx, 1); err != nil {
72			return nil, err
73		}
74		return func() {
75			s.imageProcessingSemaphore.Release(1)
76		}, nil
77	}
